void factor_max(int x, map<int, int>& mx) {
    for (int p = 2; 1LL * p * p <= x; ++p) {
        if (x % p == 0) {
            int e = 0;
            while (x % p == 0) { x /= p; ++e; }
            mx[p] = max(mx[p], e);
        }
    }
    if (x > 1) mx[x] = max(mx[x], 1);
}

long long mod_pow(long long a, int e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

